const isNoVisa = normalized.includes('no tengo visa americana');
const value = isNoVisa
  ? 'Muchas gracias por confiar en nuestra marca.\n\nTe invitamos a estar atento a todas las sorpresas y beneficios que Hyundai Ecuador tiene preparados para ti proximamente.'
  : '¡Excelente! Te deseamos mucha suerte.\n\nTe invitamos a estar atento a nuestra transmision en vivo a traves de nuestras redes oficiales de Facebook e Instagram, donde anunciaremos al ganador.';
return [{ json: { ...$json, value, visa_campaign_reply_sent: true, visa_campaign_reply_type: isNoVisa ? 'no_visa' : 'si_visa' } }];
